function queryI18n(key){
var reg = new RegExp("^" + "i18n.");
if (reg.test(key)) {
        var formate = key.substring("i18n.".length, key.indexOf(":"));
        var text = key.substring(key.indexOf(":") + 1, key.lastIndexOf(":"));
        var arg = key.substring(key.lastIndexOf(":") + 1);
        var texts = text.split("%");
        for (var i = 0; i < texts.length; i++) {
            text = eval("(dkyw.tool." + formate + "('" + text + "','" + texts[i] + "','" + queryI18n(texts[i]) + "'))");
        }
        return eval("(dkyw.tool." + formate + "('" + text + "','%','" + arg + "'))");
    }
    var value = eval("i18n_"+i18n_language_session)[key];
    if (!value) {
        value = key;
    }
    return value;
}
